import { readFile, readdir, writeFile } from 'node:fs/promises'

// Keep the public convenience entry flat: Nasti's dev CSS injection does not
// resolve relative CSS @imports. Individual adapters remain the source of truth.
const source = new URL('../src/', import.meta.url)
const themes = (await readdir(new URL('themes/', source)))
  .filter((path) => path.endsWith('.css'))
  .sort()
const paths = ['base.css', ...themes.map((path) => `themes/${path}`)]
const styles = await Promise.all(paths.map((path) => readFile(new URL(path, source), 'utf8')))
const bundle =
  [
    '/* Generated by scripts/generate-styles.mjs. Edit base.css or themes instead. */',
    ...styles.map((style) => style.trimEnd()),
  ].join('\n\n') + '\n'

await writeFile(new URL('styles.css', source), bundle)
